from pathlib import Path
import base64, gzip, re
ROOT=Path("app")
def dec(s): return gzip.decompress(base64.b64decode(s)).decode("utf-8")
JUTSU_B64=""
TREE_B64=""
(ROOT/"src/game/jutsu.ts").write_text(dec(JUTSU_B64),encoding="utf-8")
(ROOT/"src/components/JutsuTree.tsx").write_text(dec(TREE_B64),encoding="utf-8")
sw=ROOT/"public/sw.js"
text=sw.read_text(encoding="utf-8")
text,n=re.subn(r'const CACHE = "[^"]+";', 'const CACHE = "shadow-village-depth-v1-jutsu-potential-v8-four-path-jutsu";', text, count=1)
if n!=1: raise SystemExit("v8 service-worker cache anchor missing")
sw.write_text(text,encoding="utf-8")
print("Applied village depth v8: four vertical Jutsu paths per tier for elemental and rare/unique styles.")